#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int getMaximumGenerated(int n) {
        if (n == 0) return 0;
        vector<int> nums(n + 1, 0);
        nums[1] = 1;
        int max_val = 1;
        for (int i = 1; 2 * i <= n; ++i) {
            nums[2 * i] = nums[i];
            max_val = max(max_val, nums[2 * i]);
            if (2 * i + 1 <= n) {
                nums[2 * i + 1] = nums[i] + nums[i + 1];
                max_val = max(max_val, nums[2 * i + 1]);
            }
        }
        return max_val;
    }
};

class Solution {
    public int getMaximumGenerated(int n) {
        if (n == 0) return 0;
        int[] nums = new int[n + 1];
        nums[1] = 1;
        int maxVal = 1;
        for (int i = 1; 2 * i <= n; ++i) {
            nums[2 * i] = nums[i];
            maxVal = Math.max(maxVal, nums[2 * i]);
            if (2 * i + 1 <= n) {
                nums[2 * i + 1] = nums[i] + nums[i + 1];
                maxVal = Math.max(maxVal, nums[2 * i + 1]);
            }
        }
        return maxVal;
    }
}

